import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';
import 'package:vibration/vibration.dart';
import 'package:wakelock_plus/wakelock_plus.dart';

import '../engine/session_plan.dart';
import '../engine/session_runner.dart';
import 'settings_store.dart';

/// Every distinct cue. Each has its own sound (assets/sounds/, generated by
/// tool/generate_cue_sounds.dart) and vibration pattern.
enum Cue {
  getReady('get_ready', [0, 120]),
  hold1('hold1', [0, 450]),
  hold2('hold2', [0, 150, 100, 150]),
  rest('rest', [0, 80, 80, 80]),
  setRest('set_rest', [0, 80, 80, 80, 80, 80]),
  move('move', [0, 250]),
  tempoHold('tempo_hold', [0, 60, 60, 60]),
  back('back', [0, 120, 60, 120, 60, 120]),
  transition('transition', [0, 200, 100, 200]),
  wait('wait', [0, 300, 150, 300]),
  tick('tick', [0, 30]),
  finished('finished', [0, 200, 100, 200, 100, 600]);

  const Cue(this.sound, this.vibration);

  /// File name in assets/sounds/, without extension.
  final String sound;

  /// Vibration pattern: alternating wait/vibrate durations in ms.
  final List<int> vibration;

  static Cue forPhase(PhaseKind kind) => switch (kind) {
        PhaseKind.getReady => Cue.getReady,
        PhaseKind.hold1 => Cue.hold1,
        PhaseKind.hold2 => Cue.hold2,
        PhaseKind.rest => Cue.rest,
        PhaseKind.setRest => Cue.setRest,
        PhaseKind.move => Cue.move,
        PhaseKind.tempoHold => Cue.tempoHold,
        PhaseKind.back => Cue.back,
        PhaseKind.transition => Cue.transition,
        PhaseKind.waitForTap => Cue.wait,
      };
}

/// Where cues go: the device's speaker, vibrator and screen. Swapped for a
/// fake in tests.
abstract class CueOutput {
  Future<void> play(Cue cue);
  Future<void> vibrate(Cue cue);
  Future<void> setKeepAwake(bool on);
  Future<void> dispose();
}

/// Plays cues through audioplayers, vibration and wakelock_plus. Platform
/// errors are logged, never thrown: a missing cue must not stop the timer.
class DeviceCueOutput implements CueOutput {
  DeviceCueOutput() {
    _init = _preload();
  }

  final _players = <Cue, AudioPlayer>{};
  late final Future<void> _init;
  bool? _hasVibrator;

  Future<void> _preload() async {
    await _guard('audio context', () async {
      // Duck other audio (music, podcast) under a cue rather than stop it.
      await AudioPlayer.global.setAudioContext(
        AudioContextConfig(focus: AudioContextConfigFocus.duckOthers).build(),
      );
    });
    for (final cue in Cue.values) {
      await _guard('load ${cue.sound}', () async {
        final player = AudioPlayer(playerId: 'cue_${cue.sound}');
        // Android SoundPool: lowest latency for short clips.
        if (defaultTargetPlatform == TargetPlatform.android && !kIsWeb) {
          await player.setPlayerMode(PlayerMode.lowLatency);
        }
        await player.setReleaseMode(ReleaseMode.stop);
        await player.setSource(AssetSource('sounds/${cue.sound}.wav'));
        _players[cue] = player;
      });
    }
    await _guard('vibrator', () async {
      _hasVibrator = await Vibration.hasVibrator();
    });
  }

  @override
  Future<void> play(Cue cue) async {
    await _init;
    final player = _players[cue];
    if (player == null) return;
    await _guard('play ${cue.sound}', () async {
      await player.stop();
      await player.resume();
    });
  }

  @override
  Future<void> vibrate(Cue cue) async {
    await _init;
    if (_hasVibrator != true) return;
    await _guard('vibrate', () => Vibration.vibrate(pattern: cue.vibration));
  }

  @override
  Future<void> setKeepAwake(bool on) =>
      _guard('wakelock', () => WakelockPlus.toggle(enable: on));

  @override
  Future<void> dispose() async {
    // Let a cue that just started (e.g. the "finished" fanfare) play out
    // before releasing the players.
    await Future<void>.delayed(const Duration(seconds: 3));
    await _init;
    for (final p in _players.values) {
      await _guard('dispose', p.dispose);
    }
  }

  static Future<void> _guard(String what, Future<void> Function() action) async {
    try {
      await action();
    } on Object catch (e) {
      debugPrint('Cues: $what failed: $e');
    }
  }
}

/// Turns runner events into cues: a distinct sound and vibration on every
/// phase change, ticks on the last 3 s of phases of 4 s or more, and a
/// fanfare at the end. Respects the sound/vibration settings.
class CuePlayer {
  CuePlayer({
    required Stream<RunnerEvent> events,
    required this.settings,
    required this.output,
  }) {
    _subscription = events.listen(_onEvent);
  }

  final SettingsStore settings;
  final CueOutput output;
  late final StreamSubscription<RunnerEvent> _subscription;

  /// Only phases this long get the last-3-seconds ticks.
  static const tickMinPhaseSeconds = 4;

  void _onEvent(RunnerEvent event) {
    switch (event) {
      case PhaseStarted(:final phase):
        _cue(Cue.forPhase(phase.kind));
      case SecondsLeftChanged(:final phase, :final secondsLeft):
        if (phase.seconds >= tickMinPhaseSeconds &&
            secondsLeft >= 1 &&
            secondsLeft <= 3) {
          _cue(Cue.tick);
        }
      case SessionFinished():
        _cue(Cue.finished);
    }
  }

  void _cue(Cue cue) {
    if (settings.soundOn) unawaited(output.play(cue));
    if (settings.vibrationOn) unawaited(output.vibrate(cue));
  }

  Future<void> dispose() => _subscription.cancel();
}
